/** RFC 9457 problem details, served as application/problem+json. */
export interface Problem {
  /** urn:bun-jobs:error:<CODE> */
  type: string;
  title: string;
  status: number;
  code: string;
  detail?: string;
  instance?: string;
  issues?: {
    target:
      "params" | "query" | "body" | "headers" | "cookies" | "signedCookies";
    /** Dotted path within the target, or "" for the target itself. */
    path: string;
    message: string;
  }[];
  context?: Record<string, unknown>;
}

/** A provider's config as a JSON Schema, for a config form. Only for a config schema that implements Standard JSON Schema. */
export interface ProviderConfigSchema {
  /** The provider's id, as asked. */
  id: string;
  /** The JSON Schema dialect. */
  target: "draft-2020-12";
  /** The config's input JSON Schema, from `~standard.jsonSchema.input({ target })`, made secret-free. `default`, `example`, `examples`, `const` and every `x-*` key are removed everywhere (root, nested, `$defs`, combinators): a form built from it has no pre-filled values. `enum` is kept, except under a property that is a declared secret or has a credential's name, and in every definition such a property reaches through `$ref`, transitively (one reached from both a secret and a non-secret property counts as secret; a pointer into a definition counts as all of it, and one anywhere else in the document, `#` included, drops every enum). Enums with non-scalar values are dropped wherever they are. Every other string is redacted as a detail is; a string equal to a declared secret is replaced, a number equal to one dropped. */
  schema: Record<string, unknown>;
}

/** The compute providers configured in the API's process, and the plugin API versions it speaks. */
export interface ProviderList {
  api: {
    /** The core plugin API version, `major.minor`. */
    core: string;
    /** The summon facet version, `major.minor`. */
    summon: string;
  };
  /** The compute providers configured in the API's process, oldest first; empty when none is. */
  providers: {
    /** The instance's id, `name@version~<n>`: the nth instance of that `name@version` configured in the API's process. Stable for that process's life, meaningless in another. */
    id: string;
    provider: {
      /** The provider's unique name. `custom:<kind>` for one made by `defineSummoner`. Never parse it. */
      name: string;
      /** The provider's version, semver. */
      version: string;
      /** A short label for badges, e.g. `ecs`. */
      kind: string;
      /** A human name; show `kind` when absent. */
      displayName?: string;
      /** Where its documentation lives. */
      homepage?: string;
      apiVersion: {
        /** The core plugin API version, `major.minor`. */
        core: string;
        /** The summon facet version. */
        summon?: string;
      };
    };
    /** How far its config has got: `ready` (validated, facets built), `pending` (an asynchronous schema is still validating it), `failed` (the latest validation rejected, or building its facets threw). About the config alone: a controller refusing a ready provider for its policy shows on that queue's summon status, not here. */
    readiness: "ready" | "pending" | "failed";
    /** Secret-free facts from its `describe()`, `{}` until its config is known or when `describe()` throws. Dropped whatever the provider says: a fact whose key has, or ends with, a credential word (`token`, `secret`, `key`, `password`, `passwd`, `pwd`, `credential`, `auth`, `authorization`, `bearer`, `private`, `cookie`, `session`: `apiKey`, `apikey`, `sessiontoken` and `secretArn` go, `keyspace` stays), one whose value holds a URL with userinfo (`://user:pass@`) or another credential shape (`Bearer …`, a JWT, or a `word:value` / `word=value` pair whose word contains a sensitive word such as `token`, `secret`, `auth` or `session` — which also drops `session-workers:prod`, `max_tokens=4096`, an ARN with `auth-api:prod` in it), and a `host` or `hostname` fact unless `serialize.exposeHosts` is on. */
    facts: Record<string, string>;
    /** Whether it defines a preflight, so `POST /providers/{id}/validate` checks the platform and not the config alone. */
    preflight: boolean;
    /** Whether its config schema implements Standard JSON Schema, so `GET /providers/{id}/schema` answers one. */
    configSchema: boolean;
  }[];
}

/** A preflight's verdict, answered with 200 whatever the platform said. */
export interface ProviderValidation {
  /** The provider's id, as asked. */
  id: string;
  /** Whether the preflight passed: it answered, and no check is `fail`. */
  ok: boolean;
  /** What the preflight answered; empty when it threw, timed out, or the provider has none. */
  checks: {
    /** A stable id for the check, e.g. `credentials`. */
    id: string;
    /** Whether it passed; `warn` works but something is off. */
    status: "pass" | "warn" | "fail";
    /** A short explanation, redacted and cut to 128 characters. */
    detail?: string;
  }[];
  /** Why there are no checks: the config did not validate or its facets could not be built (`misconfigured`), or the preflight threw or timed out. */
  error?: {
    /** How the failure classifies, as a `ProviderError`'s kind: `auth` and `misconfigured` are the config's or the credentials' fault; `transient`, `throttled` and `quota` the platform's for now; `conflict` a provider bug. A throw that is not a `ProviderError`, and a timeout, are `transient`. */
    kind:
      | "transient"
      | "throttled"
      | "quota"
      | "auth"
      | "misconfigured"
      | "conflict";
    /** A short, secret-free explanation: the `ProviderError`'s `platformCode` (else its code), another error's code or name, `timeout`, or `invalid config: <paths>`. Redacted and cut to 128 characters. */
    detail: string;
  };
}

export interface QueueDemand {
  /** The queue's name. */
  queue: string;
  /** The instant it describes, epoch ms. */
  at: number;
  /** Whether claiming is paused. A paused queue demands nothing. */
  paused: boolean;
  /** Jobs in `waiting`. */
  waiting: number;
  /** Jobs in `delayed` or `failed` (retry pending) whose `runAt` has passed, not yet promoted. */
  dueNow: number;
  /** Jobs in `active` whose worker died holding them: what the backend's stalled sweep would recover now. */
  stalled: number;
  /** Jobs in `active`, stalled ones included. */
  active: number;
  /** Live workers on the queue, from their heartbeat records, parked and paused ones included. `0` on a backend that keeps no worker records. */
  workers: number;
  nextDueAt: number | null;
  /** `paused ? 0 : waiting + dueNow + stalled`: work a worker could claim now. What a launch-style scaler (a KEDA `ScaledJob`, an ACA event job) reads. */
  demand: number;
  /** `paused ? 0 : demand + (active − stalled)`: every unfinished job, each once. What a scale-style scaler (a KEDA `ScaledObject`, CREMA) reads, since it stays above zero while a worker is busy. */
  outstanding: number;
  /** `true` when a figure reached the count cap (10,000, `DEFAULT_DEMAND_CAP`, fixed), so the figures are lower bounds. `demand` and `outstanding` are sums of capped figures and can exceed it. */
  capped: boolean;
  /** `false` when the backend has no `countDemand` and the figures come from a fallback: `dueNow` is 1 or 0, `stalled` is `active` when no worker is live. Right as a trigger, approximate as a count. The only signal of approximate figures: `features.demand` says only that the routes are served. */
  exact: boolean;
}

export interface QueueDemandList {
  queues: QueueDemand[];
  /** Whether more queues are visible than `limits.maxQueues`, so some were not read. Only when `queues` was not sent. */
  truncated: boolean;
}

export interface QueueDetail {
  name: string;
  counts: JobCounts;
  total: number;
  paused: boolean;
  limits?: QueueLimits | null;
}

export interface QueueLimits {
  rate?: {
    max: number;
    duration: number;
  };
  concurrency?: number;
  names?: Record<
    string,
    {
      rate?: {
        max: number;
        duration: number;
      };
      concurrency?: number;
    }
  >;
}

export interface QueueSummary {
  name: string;
  counts: JobCounts;
  total: number;
  paused: boolean;
}

export interface QueueThroughput {
  interval: number;
  from: number;
  to: number;
  buckets: ThroughputBucket[];
  completed: number;
  failed: number;
}

export interface Repeatable {
  queue: string;
  key: string;
  name: string;
  opts: JobOptions;
  cron?: string;
  tz?: string;
  every?: number;
  startAt?: number;
  endAt?: number;
  limit?: number;
  catchUp?: boolean;
  count: number;
  nextRunAt: number | null;
  nextJobId: string | null;
  /** Whether the series is disabled: it schedules nothing until enabled. */
  disabled: boolean;
  createdAt: number;
  updatedAt: number;
  /** With `include=data`. */
  data?: unknown;
}

export interface RunLogLine {
  /** The line's 1-based place in its run's output, assigned by the store and never reused. A gap means the caps dropped those lines; the page's `lastSeq` sent back as `since` is the tail cursor. */
  seq: number;
  /** When it was captured, epoch ms. */
  at: number;
  stream: "stdout" | "stderr" | "log";
  /** The line's text, with its trailing newline already removed. The store calls this field `text`. */
  message: string;
  /** The severity a `log`-stream line carried. Absent on `stdout` and `stderr`, which have no levels, and on a forwarded line that came without one. */
  level?: "trace" | "debug" | "info" | "warn" | "error" | "fatal";
  /** Only ever `true`: capture cut this line at the per-line byte cap. Absent means the line is whole. */
  truncated?: true;
}

export interface RunLogPage {
  items: RunLogLine[];
  page: PageInfo;
  /** How many of this run's lines the caps have dropped, in total. The run's own number, unfiltered by `since` or `stream`. */
  dropped: number;
  /** Whether a cap is trimming this run's log right now, so the page is a moving tail. Derived by the route, not stored. */
  capped: boolean;
  /** Whether the run is still going, so more lines may follow. Derived by the route from the run's status, not stored. */
  live: boolean;
  /** The highest `seq` this run's log holds, or `0` when it holds nothing. Unfiltered, which is what makes it a correct `since` cursor for a filtered tail. */
  lastSeq: number;
}

export interface RunRecord {
  runId: string;
  runnerId: string;
  attempt: number;
  source: "schedule" | "manual" | "queued" | "resume";
  mode: "child-process" | "worker-thread" | "in-process";
  host?: string;
  pid?: number;
  startedAt: number;
  finishedAt?: number;
  durationMs?: number;
  status: "running" | "success" | "failed" | "timeout" | "killed";
  exitCode?: number | null;
  signal?: string | null;
  error?: Error;
  result?: unknown;
  detached?: boolean;
  /** Lines this run's log holds, after the caps; `0` when it logged nothing. Written when the run settles, so a run still going has neither counter — read the log route for a live count. Absent on a settled run means the backend stores no run logs, or this run's log has aged out. */
  logLines?: number;
  /** Lines the caps dropped from this run, oldest first; `0` when none were. Written with `logLines` when the run settles, and absent in the same cases. */
  logsDropped?: number;
}

export interface RunnerAnalytics {
  /** Letters, digits, "_", "." and "-", and not "." or "..". Anything else is 400 INVALID_NAME. */
  runner: string;
  runs: RunnerRunsSeries;
  /** Runs in flight **right now**, from the locks: an instant, not a figure about the range. At least this many — a run in another process in `parallel` mode holds no single-run lock to see. */
  runningNow: number;
  durations?: RunnerDurationSeries;
}

export interface RunnerAnalyticsRow {
  runner: string;
  totals: RunnerRunsTotals;
  /** Runs in flight **right now**, from the locks: an instant, not a figure about the range. At least this many — a run in another process in `parallel` mode holds no single-run lock to see. */
  runningNow: number;
  durations?: RunnerDurationTotals;
}

export interface RunnerAnalyticsSeries {
  runner: string;
  runs: RunnerRunsSeries;
}

export interface RunnerConfig {
  effective: RunnerConfigValues;
  code?: RunnerConfigValues;
  /** Setting names, in `RUNNER_CONFIG_KEYS` order. */
  overridden: ("executionMode" | "runMode" | "maxConcurrency")[];
  /** The execution modes an override may choose and this runner's owner can adopt: its `allowedOverrides.executionModes`, less `child-process` and `worker-thread` when it was built from a driver instance (unless one is its code's own mode). May be empty. Absent means all three. */
  allowed?: ("child-process" | "worker-thread" | "in-process")[];
  seq: number;
  /** The version an owner has adopted; below `seq` means it has not been picked up yet. */
  appliedSeq?: number;
  /** Why an owner refused the override, in whole or in part; absent when the last one was adopted entire. `keys` names the refused settings. */
  error?: {
    at: number;
    message: string;
    /** The settings the owner refused, in `RUNNER_CONFIG_KEYS` order; every other overridden setting was adopted. A whole-override refusal names every overridden key. `[]` on an error an owner recorded before this field existed. */
    keys: ("executionMode" | "runMode" | "maxConcurrency")[];
  };
  updatedAt?: number;
}

export interface RunnerConfigBody {
  executionMode?: "child-process" | "worker-thread" | "in-process" | null;
  concurrency?:
    | {
        runMode: "single";
      }
    | {
        runMode: "parallel";
        maxConcurrency: number | null;
      }
    | null;
}

export interface RunnerConfigValues {
  executionMode: "child-process" | "worker-thread" | "in-process";
  runMode: "parallel" | "single";
  maxConcurrency: number | null;
}

/** Runs that **finished** in the bucket. `minMs`/`maxMs`/`meanMs` are exact; `p50Ms`/`p95Ms` come from a 24-bin log histogram (ratio 2) and are always within a factor of 2 of the truth, typically within 20–30%. */
export interface RunnerDurationBucket {
  at: number;
  count: number;
  minMs: number;
  maxMs: number;
  meanMs: number;
  p50Ms?: number;
  p95Ms?: number;
  histogram?: number[];
}

/** One series: what it covers, its contiguous buckets, and their sums. */
export interface RunnerDurationSeries {
  range: AnalyticsRange;
  /** One bucket per interval, oldest first, contiguous. */
  buckets: RunnerDurationBucket[];
  totals: RunnerDurationTotals;
}

export interface RunnerDurationTotals {
  count: number;
  minMs: number;
  maxMs: number;
  meanMs: number;
  p50Ms?: number;
  p95Ms?: number;
}

export interface RunnerInfo {
  id: string;
  namespace: string;
  isLocal: boolean;
  name: string;
  file?: string;
  schedule: RunnerSchedule;
  nextRunAt: number | null;
  executionMode?: "child-process" | "worker-thread" | "in-process";
  runMode?: "parallel" | "single";
  queueRuns?: boolean;
  maxQueuedRuns?: number;
  maxConcurrency?: number;
  isPaused: boolean;
  isRunning: boolean;
  runningOn?: {
    runId: string;
    since: number;
    host?: string;
    pid?: number;
  };
  queuedTriggers: number;
  config?: RunnerConfig;
  stats: RunnerStats;
  lastRun?: RunRecord;
  lastError?: {
    name: string;
    message: string;
  };
  updatedAt?: number;
  local?: {
    /** The runner's lifecycle in its own process: `idle` = registered, not started; `running` = started with its schedule armed (a run may or may not be in flight: see `isRunning`); `paused`; `stopped`. */
    status: "idle" | "running" | "paused" | "stopped";
    activeRuns: RunRecord[];
    nextRunAt: number | null;
  };
}

export interface RunnerRunsBucket {
  at: number;
  started: number;
  succeeded: number;
  failed: number;
  timeout: number;
  killed: number;
  skipped: number;
}

/** One series: what it covers, its contiguous buckets, and their sums. */
export interface RunnerRunsSeries {
  range: AnalyticsRange;
  /** One bucket per interval, oldest first, contiguous. */
  buckets: RunnerRunsBucket[];
  totals: RunnerRunsTotals;
}

/** `started` does not balance the rest: runs straddle the range's edges. The honest in-flight number is `runningNow`. */
export interface RunnerRunsTotals {
  started: number;
  succeeded: number;
  failed: number;
  timeout: number;
  killed: number;
  skipped: number;
}

export type RunnerSchedule =
  | {
      cron: string;
      tz?: string;
    }
  | {
      every: number;
      anchor?: number;
    }
  | {
      at: number;
    }
  | null;

export interface RunnerStats {
  success: number;
  failed: number;
  timeout: number;
  killed: number;
  skipped: number;
  queued: number;
  total: number;
}

export interface RunnersAnalytics {
  series: RunnerRunsSeries;
  /** Runs in flight **right now**, from the locks: an instant, not a figure about the range. At least this many — a run in another process in `parallel` mode holds no single-run lock to see. */
  runningNow: number;
  /** A row per runner, at most 100, sorted by started runs descending then by id. */
  rows: RunnerAnalyticsRow[];
  /** Whether more rows matched than the 100 `rows` holds. */
  truncated: boolean;
  /** How many rows matched before the cap: the list the route already held, never a second read. */
  totalRows: number;
  /** One series per runner named in `ids`, in the order asked; absent when `ids` named none. */
  seriesByRunner?: RunnerAnalyticsSeries[];
}

/** Attempts counted against the summon budget in the current UTC hour and day, shared by every controller on the queue, with the answering controller's limits and when each window resets. */
export interface SummonBudget {
  /** Attempts this UTC hour. */
  hour: number;
  /** The hourly limit. Absent while the budget is off. */
  perHour?: number;
  /** Attempts this UTC day. */
  day: number;
  /** The daily limit. Absent while the budget is off. */
  perDay?: number;
  /** Present, and `true`, when the policy turned the budget off (`budget: false`): no limit applies, and the counts are shown for information. */
  off?: true;
  /** Set when no limits were stored with this state (it was written before limits were persisted): the counts are real, the limits are not known. Cleared on the queue's next summon. Only read from storage (`local: false`); `perHour`, `perDay` and `off` are then absent. */
  limitsUnknown?: true;
  /** When the hour window ends and `hour` starts again from 0, epoch ms: the next UTC hour. */
  hourResetsAt: number;
  /** When the day window ends and `day` starts again from 0, epoch ms: the next UTC midnight. */
  dayResetsAt: number;
}

export interface SummonCapabilities {
  /** How it starts compute: `launch` starts new units, `scale` sets a count, `wake` starts one of a fixed pool. */
  style: "launch" | "scale" | "wake";
  dedupe:
    | {
        /** A request token the platform remembers (ECS `clientToken`). */
        kind: "token";
        /** The longest key it accepts. */
        maxLength: number;
        /** The characters it accepts, as a character-class body. */
        charset: string;
        /** What the token is unique within, e.g. `cluster`. */
        scope: string;
        /** How long the platform remembers it, in ms, when documented. */
        ttlMs?: number;
        /** Whether a same-token request with different parameters is an error. */
        strict: boolean;
      }
    | {
        /** A name the platform will not create twice. */
        kind: "name";
        /** The longest name it accepts. */
        maxLength: number;
        /** The characters it accepts, as a character-class body. */
        charset: string;
      }
    | {
        /** No platform dedupe: the marker's compare-and-set is the whole guard. */
        kind: "none";
      };
  /** How per-attempt values reach the process: `argv`, or `none` when the command line is fixed. */
  passes: "argv" | "none";
  /** The default time an attempt counts as a worker on its way, in ms. */
  bootBudgetMs: number;
  shutdown: {
    /** The stop signal; `none` for an in-invocation platform. */
    signal: "SIGTERM" | "SIGINT" | "none";
    /** The grace after the signal, in ms. */
    graceMs: number;
    /** The most the platform allows the grace to be raised to, when known. */
    graceMaxMs?: number;
  };
  maxLifetimeMs: number | null;
  /** Whether the summoner maps the requested lifetime onto the platform's cap. */
  enforcesLifetime: boolean;
  /** The most units one call may start, when limited. */
  maxCountPerCall?: number;
  /** `wake` only: how many units the pool has. */
  poolSize?: number;
}

export interface SummonCheck {
  /** What the check did: `none` (nothing needs a worker), `skipped` (a guard held it back; see `reason`), `summoned` (an attempt was claimed and the summoner called; see `id` and `outcome`), or `released` (a scale-style summoner was set back to zero). */
  action: "none" | "skipped" | "summoned" | "released";
  /** For `skipped`: which guard held the attempt back. */
  reason?:
    | "served"
    | "pending"
    | "cooldown"
    | "backoff"
    | "circuit-open"
    | "budget"
    | "contended"
    | "closed"
    | "inert";
  /** For `summoned`: the attempt's id. */
  id?: string;
  /** For `summoned`: what the summoner answered, or `failed`. */
  outcome?:
    | "started"
    | "deduped"
    | "already-running"
    | "registered"
    | "unavailable"
    | "failed"
    | "lost"
    | "budget-exhausted"
    | "released";
  demand?: QueueDemand;
}

/** Every summon group with shared state in the namespace, read from storage. */
export interface SummonGroupList {
  /** The groups, in name order. Empty when none has state. */
  groups: SummonGroupStatus[];
}

/** A summon group's shared state (`SummonPolicy.group`): the attempts counted against the group in the current UTC hour and day across every queue in it, with the limits for the group — the answering controller's, or read from storage the ones the last charge persisted (absent, and `off: true`, while the group's budget is off) — each queue's share of today's, and its shared circuits. */
export interface SummonGroupStatus {
  /** The group's name. */
  name: string;
  /** `shared` when the group is one shared unit (`group.unit: "shared"`): one controller summons for all of its queues, and the unit's attempts, failures and circuit are kept in the group's state, so `GET /queues/{queue}/summon` on any of its queues answers them. From a controller in the group, its policy says so; read from storage, the group's state does, once the unit has claimed. Absent for a group of per-queue controllers. */
  unit?: "shared";
  budget: SummonBudget;
  /** Each queue's share of today's attempts, by queue name: every queue that charged the group since UTC midnight. */
  queues: Record<
    string,
    {
      /** Attempts this queue charged to the group this UTC day. */
      day: number;
      /** When it last charged one, epoch ms. */
      lastAt: number;
    }
  >;
  /** The group's shared circuit for the answering controller's summoner kind, when a controller in the group runs in the API's process and its group shares its circuit (`group.circuit`) — or, read from storage, the kind a queue's last claim persisted: while open, no queue of the group using that kind is summoned for. */
  circuit?: {
    /** Consecutive failures counted across the group for this provider kind; reset by a registration on any of its queues. */
    failures: number;
    /** When the open circuit closes, epoch ms, while it is open. */
    openUntil?: number;
    /** The failure that last opened it. */
    openedBy?: {
      /** The queue whose attempt failed. */
      queue: string;
      /** The attempt. */
      id: string;
      /** Its short, secret-free detail. */
      detail?: string;
    };
  };
  /** Every provider kind's shared circuit the group's state holds, by `kind`, as `circuit` shows one, so any API process shows every kind's. Absent while none has counted a failure. */
  circuits?: Record<
    string,
    {
      /** Consecutive failures counted across the group for this provider kind; reset by a registration on any of its queues. */
      failures: number;
      /** When the open circuit closes, epoch ms, while it is open. */
      openUntil?: number;
      /** The failure that last opened it. */
      openedBy?: {
        /** The queue whose attempt failed. */
        queue: string;
        /** The attempt. */
        id: string;
        /** Its short, secret-free detail. */
        detail?: string;
      };
    }
  >;
}

/** Every summoning queue the API can read, with its budget usage and circuit. */
export interface SummonList {
  /** Every summoning queue, by queue name — with a controller in the API's process (`local: true`) or summon state in storage (`local: false`) — less the queues the caller may not read. Empty when none summons. */
  controllers: {
    /** The queue's namespace. */
    namespace: string;
    /** The queue. A shared unit (`group.unit: "shared"`) is one item, whose `queue` is the first of its `queues` the caller may read. */
    queue: string;
    /** For a shared unit (`group.unit: "shared"`): the queues it serves that this API can reach and the caller may read (`queues.read`), in the policy's order, the first being `queue`. A shared unit is listed once, and only when the caller may read at least one of its queues; a `partial:` detail on `last` names only these queues. Absent for a controller of one queue. */
    queues?: string[];
    /** For a shared unit: the summon group it is the unit of (`SummonPolicy.group.name`), as `group.name` of `GET /queues/{queue}/summon` has it. Absent for a controller of one queue (its group, if any, is on its own status). */
    group?: string;
    /** Whether its controller runs in the API's process. `false`: read from the queue's summon state in storage, as `GET /queues/{queue}/summon` answers with `local: false`; then `readiness` is absent. */
    local: boolean;
    /** The summoner's kind, e.g. `ecs`: a label for badges. Read from storage, the kind the queue's last claim persisted, empty when none did. */
    kind: string;
    /** Whether the summoner can be called, as `GET /queues/{queue}/summon` has it: `ready`, `pending` while its provider's config is still validating, or `failed`. Only when `local`. */
    readiness?: "ready" | "pending" | "failed";
    /** Whether the controller is inert, as `GET /queues/{queue}/summon` has it: it summons nothing, whatever `readiness` says. Read from storage (`local: false`), `true` only for summon state a newer bun-jobs wrote (`inertReason: newer-marker`). */
    inert?: boolean;
    /** Why it is inert, as `GET /queues/{queue}/summon` has it: `summoned-process` (the API's process was itself summoned, or is a runner child, and the policy has no `fromSummoned`) or `newer-marker` (a newer bun-jobs wrote the queue's summon state). Never `unreadable-marker` here: the list leaves a queue whose summon state cannot be read out. */
    inertReason?: "summoned-process" | "newer-marker" | "unreadable-marker";
    /** When the queue's open circuit closes, epoch ms, while it is open, as `GET /queues/{queue}/summon` has it. */
    circuitOpenUntil?: number;
    last?: {
      /** The attempt it concerns; empty for an outcome no attempt owns. */
      id: string;
      /** What happened. Show an outcome you do not know as the raw string. */
      outcome:
        | "started"
        | "deduped"
        | "already-running"
        | "registered"
        | "unavailable"
        | "failed"
        | "lost"
        | "budget-exhausted"
        | "released";
      /** When, epoch ms. */
      at: number;
      /** A short, secret-free explanation. */
      detail?: string;
      /** For a shared unit's partial registration (`outcome: registered`, detail `partial:<queues>`): the queues its attempt registered no worker on, in the policy's order, the same ones the detail names. Stored with the outcome, so a status read from storage (`local: false`) has it too. Absent otherwise, and on an outcome an older bun-jobs wrote, whose detail still names them. Only the queues the caller may read; `detail` then names the same ones. */
      missing?: string[];
    };
    budget?: SummonBudget;
  }[];
}

/** The policy a queue's summon controller runs with, as it resolved it: every value in effect, defaults filled in, durations in ms. Never an `env` value, a summoner, or the provider's config. Field names are the policy's option names, so a path in `explicit` is the field's path here, except `group.circuit.*` (shown as `circuit.group`) and the budget (shown by the status's `budget` and `group.budget`). The platform's shutdown signal and grace are not a policy value: read them from `summoner.capabilities.shutdown`. */
export interface SummonPolicyStatus {
  /** What makes the controller check: one item per trigger kind, on or off, in `onAdd`, `events`, `poll` order. */
  triggers: {
    /** Which trigger: `onAdd` (a job added through a queue the controller is attached to), `events` (an event another process published through the driver) or `poll`. Show a kind you do not know as text. */
    kind: "onAdd" | "events" | "poll";
    /** Whether it is on. */
    on: boolean;
    /** `onAdd` and `events`: how long add and event triggers are coalesced (`triggers.debounce`), in ms. */
    debounce?: number;
    /** `poll`, while on: how often the controller checks, in ms. */
    every?: number;
  }[];
  /** How long an attempt counts as a worker on its way: the policy's `bootBudget`, else the summoner's `capabilities.bootBudgetMs`. Absent while the summoner is not ready and the policy set none (the default is not known yet), in ms. */
  bootBudget?: number;
  /** The most summoned workers at once. Once the summoner is ready, the value after a wake pool's clamp to its `poolSize`; while it is not (`readiness` `pending` or `failed`), the configured value, before that clamp, since the pool's size is not known yet. */
  maxWorkers: number;
  jobsPerWorker: number | null;
  /** The most unregistered attempts at once (defaults to `maxWorkers`, so a default follows `maxWorkers`: after a wake pool's clamp once the summoner is ready, before it while it is not). */
  maxPending: number;
  /** The least time between two attempts, in ms. */
  cooldown: number;
  /** The wait after a failed or lost attempt: `initial`, doubling per consecutive failure, up to `max`. */
  backoff: {
    /** The first wait, in ms. */
    initial: number;
    /** The longest wait, in ms. */
    max: number;
  };
  /** Consecutive failed or lost attempts that open the circuit, and how long it stays open before a trial. */
  circuit: {
    /** Consecutive failed or lost attempts that open it. */
    failures: number;
    /** How long it stays open before one trial attempt, in ms. */
    resetAfter: number;
    /** The summon group's shared circuit thresholds, when `group.circuit` is on for a per-queue controller (each defaulting to the policy's own). Absent otherwise, and for a shared unit, whose circuit is its group's own. */
    group?: {
      /** Consecutive failures across the group, of one provider kind, that open it. */
      failures: number;
      /** How long it stays open, in ms. */
      resetAfter: number;
    };
  };
  /** The longest a summoned worker may live (passed as `--bun-jobs-summon-max-lifetime-ms`); the platform's own cap is `summoner.capabilities.maxLifetimeMs`, in ms. */
  maxLifetime: number;
  /** Which live workers count as serving the queue. */
  servedBy: "any-worker" | "summoned-only";
  /** Scale style only: when the count goes back to zero. */
  scaleDown: {
    /** How long the queue must be idle first, in ms. */
    after: number;
  };
  /** How long one summoner call may take, in ms. */
  summonTimeout: number;
  /** The names of the policy's static `env`, sorted. Never their values. */
  env: string[];
  /** Whether the controller may run in a summoned process or runner child. */
  fromSummoned: boolean;
  /** Whether an `onSummonFailed` hook is set. */
  onSummonFailed: boolean;
  /** A shared unit only (`group.unit: "shared"`): each of its queues' capacity, by queue, in the unit's order — only the queues the caller may read (`queues.read`) and this API can reach, as `queues` has them. Absent for a controller of one queue. Its keys are in the unit's order, except that queue names that look like integers (`"2"`) come first, in ascending order, as JavaScript orders an object's keys. */
  perQueue?: Record<
    string,
    {
      jobsPerWorker: number | null;
      /** The most units this queue's demand alone may ask for: at most `maxWorkers`, so clamped as it is. */
      maxWorkers: number;
      /** What the unit's `overrides` entry for this queue set, in this order. */
      explicit: ("jobsPerWorker" | "maxWorkers")[];
    }
  >;
  /** The keys the policy set (any value but `undefined`), in `SUMMON_POLICY_KEYS` order; every other value is a default. A per-queue group member's override is merged into its policy, so its keys count as set too. On a shared unit, whose circuit is its group entry's own, `group.circuit.*` is never listed (it changes nothing there, and `circuit.group` is absent). */
  explicit: (
    | "triggers.onAdd"
    | "triggers.events"
    | "triggers.poll"
    | "triggers.debounce"
    | "bootBudget"
    | "maxWorkers"
    | "jobsPerWorker"
    | "maxPending"
    | "cooldown"
    | "backoff.initial"
    | "backoff.max"
    | "circuit.failures"
    | "circuit.resetAfter"
    | "group.circuit.failures"
    | "group.circuit.resetAfter"
    | "budget"
    | "budget.perHour"
    | "budget.perDay"
    | "maxLifetime"
    | "servedBy"
    | "scaleDown.after"
    | "summonTimeout"
    | "env"
    | "fromSummoned"
    | "onSummonFailed"
  )[];
}

/** A queue's summon status: its shared summon state (read from the backend, so the same from every process) plus the local controller's policy (`policy`: only when `local` is `true`, since only the process running the controller knows it; advertised by `/meta.features.summonPolicy`). */
export interface SummonStatus {
  /** The queue. For a shared unit, the first of `queues`: the first of its queues the caller may read. */
  queue: string;
  /** For a shared unit (`group.unit: "shared"`): the queues it serves that the caller may read (`queues.read`, asked as this route asks it) and this API can reach (its `queues` option: reachability, not access control), in the policy's order, always including the one asked about. The status is the unit's, the same whichever of its queues was asked about, and `queue` is the first of these; a `partial:` detail on `last` names only these queues too (bare `partial` when it names none of them). Read from storage (`local: false`), of the queues its last claim persisted. Absent for a controller of one queue. */
  queues?: string[];
  /** Summon groups whose shared units also summon for this controller's queues, as of its last check: the group named on live summoned worker records of its queues, other than its own. One queue with two summoning controllers can start a unit for each in a cold start. Only the groups seen on queues the caller may read (`queues.read`). Sorted; absent when there are none, before the first check, and read from storage (`local: false`). A per-queue controller's unit writes no group on its records, so it is never listed. */
  overlaps?: string[];
  /** Whether the controller runs in the API's process. `false`: read from the queue's summon state in storage, for a queue whose controller runs elsewhere — no `summoner`, the budget's limits the ones its last claim persisted (`off` when its budget was off, absent when none was persisted; for a shared unit, the group's own limits, since a stricter `budget` in its policy is known only to its controller), and "summon now" and reset still 409 `SUMMON_NOT_CONFIGURED`. A queue a shared unit in another process serves is answered with the unit's status, read from its group's state, when the unit claimed at or after the queue's own summon state did. Advertised by `/meta.features.summonStoredStatus`. */
  local: boolean;
  /** Whether that controller is inert: it summons nothing, and "summon now" answers `skipped` with reason `inert`. Read from storage (`local: false`), `true` only for summon state this build cannot read: state a newer bun-jobs wrote, or state not in the shape of summon state at all (with nothing pending, no failures and no `budget`). */
  inert: boolean;
  /** Why it is inert: `summoned-process` (the API's process was itself summoned, or is a runner child, and the policy has no `fromSummoned`), `newer-marker` (a newer bun-jobs wrote the queue's summon state) or `unreadable-marker` (the queue's summon state cannot be read at all; `GET /summon` leaves such a queue out). Show a reason you do not know as text. */
  inertReason?: "summoned-process" | "newer-marker" | "unreadable-marker";
  summoner?: {
    provider: {
      /** The provider's unique name. `custom:<kind>` for one made by `defineSummoner`. Never parse it. */
      name: string;
      /** The provider's version, semver. */
      version: string;
      /** A short label for badges, e.g. `ecs`. */
      kind: string;
      /** A human name; show `kind` when absent. */
      displayName?: string;
      /** Where its documentation lives. */
      homepage?: string;
      apiVersion: {
        /** The core plugin API version, `major.minor`. */
        core: string;
        /** The summon facet version. */
        summon?: string;
      };
    };
    /** The configured provider's id in the API's process, `name@version~<n>`: what `POST /providers/{id}/validate` ("Test connection") and `GET /providers/{id}/schema` take, percent-encoded. Stable for that process's life. Absent only for a summoner nothing can trace to a configured instance. */
    providerId?: string;
    /** Whether the summoner can be called: `ready`; `pending` while its provider's asynchronous config check is still running; `failed` when that check rejected (each attempt fails without a call and validates again; the redacted detail is on `last.detail`) or this queue's controller refused the provider for good for its policy (then `GET /providers` still says `ready`: that readiness is the config's alone). */
    readiness: "ready" | "pending" | "failed";
    capabilities?: SummonCapabilities;
    /** Secret-free facts from the summoner's `describe()`, `{}` until its config is known. Dropped whatever the provider says: a fact whose key has, or ends with, a credential word (`token`, `secret`, `key`, `password`, `passwd`, `pwd`, `credential`, `auth`, `authorization`, `bearer`, `private`, `cookie`, `session`: `apiKey`, `apikey`, `sessiontoken` and `secretArn` go, `keyspace` stays), one whose value holds a URL with userinfo (`://user:pass@`) or another credential shape (`Bearer …`, a JWT, or a `word:value` / `word=value` pair whose word contains a sensitive word such as `token`, `secret`, `auth` or `session` — which also drops `session-workers:prod`, `max_tokens=4096`, an ARN with `auth-api:prod` in it), and a `host` or `hostname` fact unless `serialize.exposeHosts` is on. */
    facts: Record<string, string>;
  };
  /** Attempts in flight, oldest first. */
  pending: {
    /** The attempt's id: what the summoned worker's `summon.id` will say. */
    id: string;
    /** When it was claimed, epoch ms. */
    at: number;
    /** When it stops counting as a worker on its way, epoch ms: past it, with no worker registered, the attempt is `lost`. */
    until: number;
    /** How many workers it asked for. */
    count: number;
    /** The summoner's kind. */
    kind: string;
    /** The platform's identifiers for what it started. Omitted unless `serialize.exposeSummonHandles` is on (default off): a task ARN carries the AWS account id. */
    handles?: string[];
    /** For a shared unit (`group.unit: "shared"`): how far this attempt has got on each queue the unit serves, by queue. `registered` once a worker of the unit holds the attempt's claim on that queue and is live there, or has left with a clean exit mark; `missing` once the attempt's `until` has passed with no worker registered there and none still starting, by the server's clock plus the 5 s allowance the controller grants every comparison between processes; `pending` before that. Worked out from the queues' claims and live worker records each time the status is read: never stored, and absent for a controller of one queue and when those reads fail (the status is then answered without it). An attempt with a `missing` queue settles at the controller's next check as `registered` with `partial:<queues>` (see `last.missing`), or as `lost` when every queue is missing. Only the queues the caller may read (`queues.read`). */
    coverage?: Record<string, "registered" | "pending" | "missing">;
  }[];
  /** Consecutive failed or lost attempts; reset by a registration or a reset. */
  failures: number;
  /** When the backoff after a failure ends, epoch ms, while one runs. */
  backoffUntil?: number;
  /** When the open circuit closes, epoch ms, while it is open. */
  circuitOpenUntil?: number;
  budget?: SummonBudget;
  last?: {
    /** The attempt it concerns; empty for an outcome no attempt owns. */
    id: string;
    /** What happened. Show an outcome you do not know as the raw string. */
    outcome:
      | "started"
      | "deduped"
      | "already-running"
      | "registered"
      | "unavailable"
      | "failed"
      | "lost"
      | "budget-exhausted"
      | "released";
    /** When, epoch ms. */
    at: number;
    /** A short, secret-free explanation. */
    detail?: string;
    /** For a shared unit's partial registration (`outcome: registered`, detail `partial:<queues>`): the queues its attempt registered no worker on, in the policy's order, the same ones the detail names. Stored with the outcome, so a status read from storage (`local: false`) has it too. Absent otherwise, and on an outcome an older bun-jobs wrote, whose detail still names them. Only the queues the caller may read; `detail` then names the same ones. */
    missing?: string[];
  };
  group?: SummonGroupStatus;
  policy?: SummonPolicyStatus;
}

export interface ThroughputBucket {
  at: number;
  completed: number;
  failed: number;
}

export type TriggerOutcome =
  | {
      outcome: "started";
      runId: string;
    }
  | {
      outcome: "queued";
      position: number;
    }
  | {
      outcome: "skipped";
      reason:
        | "paused"
        | "busy"
        | "lock-held"
        | "max-concurrency"
        | "queue-full"
        | "stopped";
    };

export interface Worker {
  id: string;
  /** The stable identity a config override is keyed by; absent on a worker that predates remote control. */
  key?: string;
  service?: string;
  queue: string;
  state?: WorkerState;
  concurrency: number;
  active: number;
  paused: boolean;
  startedAt: number;
  processStartedAt?: number;
  heartbeatAt: number;
  expiresAt: number;
  /** Whether it has missed a report (over 1.5 × its effective `reportInterval`): listed, but late. Absent when it reports no config to judge it by. */
  stale?: boolean;
  version?: string;
  /** Jobs this incarnation has completed since it started, as of its last report. Per incarnation; absent on an older worker. */
  completed?: number;
  /** Attempts this incarnation has failed since it started, as of its last report. Absent on an older worker. */
  failed?: number;
  /** Resident set size in bytes at its last report (`process.memoryUsage.rss()`). The memory of the **process**, not of the worker: two workers in one process report the same number, so never sum it across rows — take one row per `pid` (with `host`). Absent on an older worker. */
  rssBytes?: number;
  /** How long this worker's own heartbeat record write took, in milliseconds: the round trip to the driver, not a network ping. The **last sample**, not an average — a write cannot time itself, so it is the previous report's. Absent on a worker's first report and on an older worker. */
  heartbeatRttMs?: number;
  /** Whether this worker **takes part in** the queue's housekeeping sweeps — the minute pass: pruning expired results, healing repeat series, sweeping stale queue state — which is what its `maintenance` option decides. Taking part, not performing: the minute pass is leased, so on a queue of five `true` workers exactly one holds the lease on any given pass and the rest stand down — do not show it as "sweeping now". It says nothing about liveness: promoting delayed jobs, recovering stalled ones and healing flows happen on every worker and cannot be turned off. Absent on an older worker, and absent is **not** `false`: it means too old to say — so a queue counts as having no sweeper only when at least one live worker reports `false` and none reports `true`, never merely because none reports it at all. */
  sweeps?: boolean;
  target?: WorkerTargetInfo;
  summon?: WorkerSummonProvenance;
  config?: WorkerConfig;
  control?: WorkerControl;
  /** Omitted with `serialize.exposeHosts: false`. */
  host?: string;
  /** Omitted with `serialize.exposeHosts: false`. */
  pid?: number;
}

export interface WorkerAnalytics {
  key: string;
  queue: string;
  jobs: WorkerJobsSeries;
  busyness?: WorkerBusynessSeries;
}

export interface WorkerAnalyticsRow {
  /** The worker's stable key — never the per-incarnation id. */
  key: string;
  queue: string;
  totals: WorkerJobsTotals;
  busyness?: WorkerBusynessTotals;
}

export interface WorkerAnalyticsSeries {
  key: string;
  queue: string;
  jobs: WorkerJobsSeries;
}

/** Sampled on the worker's heartbeat, not counted. `samples: 0` means the worker was not reporting, not that it was idle. */
export interface WorkerBusynessBucket {
  at: number;
  samples: number;
  activeMean: number;
  activeMax: number;
  concurrency: number;
}

/** One series: what it covers, its contiguous buckets, and their sums. */
export interface WorkerBusynessSeries {
  range: AnalyticsRange;
  /** One bucket per interval, oldest first, contiguous. */
  buckets: WorkerBusynessBucket[];
  totals: WorkerBusynessTotals;
}

export interface WorkerBusynessTotals {
  samples: number;
  activeMean: number;
  activeMax: number;
  concurrency: number;
}

export interface WorkerConfig {
  effective: WorkerConfigValues;
  code: WorkerConfigValues;
  /** Setting names, in `WORKER_CONFIG_KEYS` order. */
  overridden: (
    | "concurrency"
    | "pollInterval"
    | "maxBlock"
    | "lockDuration"
    | "heartbeatInterval"
    | "stalledInterval"
    | "maxStalledCount"
    | "reportInterval"
    | "drainDelay"
  )[];
  /** Setting names, in `WORKER_CONFIG_KEYS` order. */
  derived?: (
    | "concurrency"
    | "pollInterval"
    | "maxBlock"
    | "lockDuration"
    | "heartbeatInterval"
    | "stalledInterval"
    | "maxStalledCount"
    | "reportInterval"
    | "drainDelay"
  )[];
  seq: number;
  updatedAt?: number;
}

export interface WorkerConfigBody {
  concurrency?: number | null;
  pollInterval?: number | null;
  maxBlock?: number | null;
  lockDuration?: number | null;
  heartbeatInterval?: number | null;
  stalledInterval?: number | null;
  maxStalledCount?: number | null;
  reportInterval?: number | null;
  drainDelay?: number | null;
  /** The `seq` last read. Answered 409 CONTROL_CONTENDED when it no longer matches. Omit it for a last-writer-wins write. */
  expectedSeq?: number;
}

export interface WorkerConfigOverride {
  queue: string;
  key: string;
  values: WorkerConfigPatch;
  seq: number;
  updatedAt: number;
  /** Live workers carrying this key, and whether each has applied this version. */
  instances: {
    id: string;
    applied: boolean;
  }[];
}

/** The settings an override replaces; a key absent from it is left at the worker's own value. */
export interface WorkerConfigPatch {
  /** 1 … 1000. */
  concurrency?: number;
  /** 10 … 3600000, in ms. */
  pollInterval?: number;
  /** 10 … 3600000, in ms. */
  maxBlock?: number;
  /** 1000 … 86400000, in ms. */
  lockDuration?: number;
  /** 100 … 43200000, in ms. */
  heartbeatInterval?: number;
  /** 1000 … 86400000, in ms. */
  stalledInterval?: number;
  /** 0 … 100. */
  maxStalledCount?: number;
  /** 1000 … 600000, in ms. */
  reportInterval?: number;
  /** 0 … 86400000, in ms. */
  drainDelay?: number;
}

export interface WorkerConfigResult {
  queue: string;
  key: string;
  values: WorkerConfigPatch;
  seq: number;
  /** The live workers it reaches, and whether each has applied it yet. */
  instances: {
    id: string;
    applied: boolean;
    state?: WorkerState;
  }[];
}

/** Every editable worker setting: milliseconds except `concurrency` and `maxStalledCount`, which are counts. */
export interface WorkerConfigValues {
  /** 1 … 1000. */
  concurrency: number;
  /** 10 … 3600000, in ms. */
  pollInterval: number;
  /** 10 … 3600000, in ms. */
  maxBlock: number;
  /** 1000 … 86400000, in ms. */
  lockDuration: number;
  /** 100 … 43200000, in ms. */
  heartbeatInterval: number;
  /** 1000 … 86400000, in ms. */
  stalledInterval: number;
  /** 0 … 100. */
  maxStalledCount: number;
  /** 1000 … 600000, in ms. */
  reportInterval: number;
  /** 0 … 86400000, in ms. */
  drainDelay: number;
}

export interface WorkerControl {
  /** Whether the worker listens for control at all: its `control` option, and a backend that can store the desired state. */
  enabled: boolean;
  /** How it hears about a change: a driver subscription, or only its own polling. */
  mode: "subscribe" | "poll";
  appliedSeq: number;
  configSeq: number;
  /** Whether it is mid-apply — `state === "restarting"`. */
  pending: boolean;
  stopPersistence: WorkerStopPersistence;
  /** Whether one request may override `stopPersistence` by sending `persist` on the stop route. */
  stopPersistenceOverridable: boolean;
  lastError?: {
    at: number;
    message: string;
    action?: "pause" | "resume" | "stop" | "start" | "config" | "reset";
    seq?: number;
  };
}

export interface WorkerControlBody {
  /** Wait up to this many ms for the worker to acknowledge. `0` (the default) stores the instruction and answers 202 at once. At most 30000. `?wait=` is the spelling a client uses, and wins over this one. */
  wait?: number;
  /** `stop` only: abandon the jobs still running after this many ms instead of waiting for them. Their locks then lapse and another worker recovers them as stalled — the work is delayed and run again from the start, which is why waiting is the default. At most 3600000. */
  timeout?: number;
  persist?: WorkerStopPersistence;
}

export interface WorkerControlResult {
  /** The state that was asked for. `stopping` and `restarting` are transients a caller never requests. */
  desired: "running" | "paused" | "stopped";
  seq: number;
  /** Whether the worker has been seen to apply it — always `false` without `wait`, unless it was already in that state. */
  applied: boolean;
  persisted?: WorkerStopPersistence;
  worker?: Worker;
}

export interface WorkerJobsBucket {
  at: number;
  completed: number;
  failed: number;
}

/** One series: what it covers, its contiguous buckets, and their sums. */
export interface WorkerJobsSeries {
  range: AnalyticsRange;
  /** One bucket per interval, oldest first, contiguous. */
  buckets: WorkerJobsBucket[];
  totals: WorkerJobsTotals;
}

export interface WorkerJobsTotals {
  completed: number;
  failed: number;
}

/** What the worker is doing. `stopping` and `restarting` are transients it passes through. */
export type WorkerState =
  "running" | "paused" | "stopping" | "stopped" | "restarting";

/** `"process"`: only this incarnation is stopped, so a redeploy brings the worker back running. `"key"`: the stop is stored against the stable key, so every replica — including one started later — comes up stopped. */
export type WorkerStopPersistence = "process" | "key";

/** Where a summoned worker came from — the worker record's `summon`. Absent means one of two things, and a client cannot tell which: the worker was not summoned, or it is too old to say. So show absence as no badge, never as a claim about how the worker was started. */
export interface WorkerSummonProvenance {
  /** The summon attempt's id: always present on a summoned worker. */
  id: string;
  /** The summoner's kind, e.g. `"ecs"` or `"fly"`: what a badge names. */
  kind?: string;
  /** The platform's own name for the unit (a task ARN, a Fly machine id). Omitted unless `serialize.exposeSummonHandles` is on (default off): an ECS task ARN contains the AWS account id. */
  handle?: string;
  /** The mode as requested by the summoner: `"exit-on-idle"`, `"until-stopped"` or `"in-invocation"`. Absent when none was requested, never defaulted. Show a mode you do not know as the raw string: a later server may add one. */
  mode?: "exit-on-idle" | "until-stopped" | "in-invocation";
  /** The latest it should stop, epoch ms, as requested by the summoner. Absent when none was requested, never defaulted. */
  deadlineAt?: number;
  /** The summon group whose shared unit this worker belongs to, when the unit was summoned for several queues: what a badge shows as "unit of media". Absent for a unit summoned for one queue, never defaulted. */
  group?: string;
  /** The mode the worker actually runs in, as `runSummoned` resolved it: its own option, else the requested `mode`, else `"exit-on-idle"` — so it may be present with no `mode`. Absent on a worker not run by `runSummoned`, or too old to say. Show a mode you do not know as the raw string. */
  resolvedMode?: "exit-on-idle" | "until-stopped" | "in-invocation";
}

/** Where a worker's attempts run, and whether it runs a function or a file — the worker record's `target`. Absent on an older worker, and absent is **not** `"in-process"`: it means too old to say, so show it as unknown, never as the default. Unrelated to the `target` of a worker event's envelope, which is the queue name. */
export interface WorkerTargetInfo {
  /** Where the attempts run: `"in-process"`, `"worker-thread"`, `"child-process"`, `"container"`, or `"custom"` (a target the application supplied). Show a kind you do not know as the raw string: a later server may add one. */
  kind:
    "in-process" | "worker-thread" | "child-process" | "container" | "custom";
  /** Whether the attempts run a function or a processor file. The pairs that occur: `"in-process"` with `"function"` or `"file"`; `"worker-thread"`, `"child-process"` and `"container"` with `"file"` only (a function cannot be sent to a thread, a process or a container); `"custom"` with `"function"` or `"file"`. */
  processor: "function" | "file";
  /** For `"custom"`: the target's own name. Absent for every other kind. */
  name?: string;
  /** For `"container"`: the image each attempt runs in and the runtime it asked for. Never the container's environment. Absent for every other kind. */
  container?: {
    /** The image, exactly as the target names it: `name@sha256:…` or `name:tag`. */
    image: string;
    /** The OCI runtime the target asked for, e.g. `"runsc"`; absent for the engine's default. */
    runtime?: string;
  };
  /** For a file processor: the absolute path it resolved to. Omitted unless `serialize.exposeProcessorFiles` is on. */
  file?: string;
}

export interface WorkersAnalytics {
  series: WorkerJobsSeries;
  /** A row per worker key, at most 100, sorted by `completed` descending then by key. */
  rows: WorkerAnalyticsRow[];
  /** Whether more rows matched than the 100 `rows` holds. */
  truncated: boolean;
  /** How many rows matched before the cap: the list the route already held, never a second read. */
  totalRows: number;
  /** One series per (queue, key) the keys in `keys` matched, in the order asked; absent when `keys` named none. */
  seriesByKey?: WorkerAnalyticsSeries[];
}

